private HWND _previewPlacementWindowHandle;
private HWND ResolvePreviewPlacementWindowHandle(SelectedItem selectedItem)
{
    var peekWindowHandle = new HWND(this.GetWindowHandle());
    if (TitleBarControl.Pinned) return peekWindowHandle;
    return selectedItem is SelectedItemByWindowHandle byWindow && byWindow.WindowHandle != HWND.Null ? byWindow.WindowHandle : peekWindowHandle;
}
private void Initialize(SelectedItem selectedItem)
{
    _previewPlacementWindowHandle = ResolvePreviewPlacementWindowHandle(selectedItem);
    ViewModel.Initialize(selectedItem);
    if (ViewModel.CurrentItem == null) return;
    ViewModel.ScalingFactor = _previewPlacementWindowHandle.GetMonitorScale();
}

private HWND GetPreviewPlacementWindowHandleOrFallback() => _previewPlacementWindowHandle != HWND.Null ? _previewPlacementWindowHandle : new HWND(this.GetWindowHandle());
private void FilePreviewer_PreviewSizeChanged(object sender, PreviewSizeChangedArgs e)
{
    var monitorWindowHandle = GetPreviewPlacementWindowHandleOrFallback();
    var monitorSize = monitorWindowHandle.GetMonitorSize();
    var monitorScale = monitorWindowHandle.GetMonitorScale();
    if (!TitleBarControl.Pinned) this.CenterOnMonitor(monitorWindowHandle, desiredWindowWidth, desiredWindowHeight);
    this.Show();
    WindowHelpers.BringToForeground(this.GetWindowHandle());
}
